WITH prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) AS prev_event_time FROM web_events), gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT session_id, DATE_TRUNC('YEAR', prev_event_time) AS year_start, page, SORT_ARRAY(COLLECT_SET(page)) AS page_list, SUM(CASE WHEN page = '/product' THEN new_group_flag ELSE 0 END) AS product_new_group_flag, MAX(event_time) AS ended_at FROM islands GROUP BY session_id, DATE_TRUNC('YEAR', prev_event_time), page HAVING product_new_group_flag >= 0 ORDER BY year_start NULLS LAST;
